INSERT INTO meeting_summaries (id, meeting_id, status, summary_text, generated_by, model, generated_at, last_reviewed_by_user_id, last_reviewed_at) VALUES ('summary_nw_q2', 'meeting_nw_q2', 'generated', 'We reviewed Q2 carrier performance against the renegotiated SLAs. On-time delivery climbed to 94.2%, but two coastal lanes continued to underperform and are dragging the regional average. The team agreed that consolidating those lanes under a single carrier is the most viable path before peak season.
INSERT INTO meeting_summary_key_points (id, summary_id, text, sort_order) VALUES ('key_summary_nw_q2_1', 'summary_nw_q2', 'On-time delivery improved to 94.2%.', 0);
INSERT INTO meeting_summary_key_points (id, summary_id, text, sort_order) VALUES ('key_summary_nw_q2_2', 'summary_nw_q2', 'Two coastal lanes are still underperforming.', 1);
INSERT INTO meeting_summary_key_points (id, summary_id, text, sort_order) VALUES ('key_summary_nw_q2_3', 'summary_nw_q2', 'Carrier consolidation is the preferred path before peak season.', 2);
INSERT INTO meeting_summary_key_points (id, summary_id, text, sort_order) VALUES ('key_summary_nw_q2_4', 'summary_nw_q2', 'A revised SLA draft needs to circulate this week.', 3);
INSERT INTO meeting_summary_decisions (id, summary_id, text, owner_entity_type, owner_entity_id, created_at) VALUES ('decision_nw_q2_1', 'summary_nw_q2', 'Consolidate the underperforming coastal lanes under one carrier before peak season.', 'contact', 'contact_marcus_reed', '2026-06-12T16:05:00Z');
INSERT INTO meeting_summary_risks (id, summary_id, text, severity, owner_entity_type, owner_entity_id) VALUES ('risk_nw_q2_1', 'summary_nw_q2', 'The WMS rollout may change KPI baselines and affect July reporting.', 'medium', 'contact', 'contact_dana_whitlock');
