INSERT INTO transcript_segments (id, transcript_id, speaker_entity_type, speaker_entity_id, speaker_name, start_seconds, end_seconds, text, sort_order) VALUES ('segment_nw_q2_3', 'transcript_nw_q2', 'contact', 'contact_priya_nair', 'Priya Nair', 47, 67, 'If we close renewals by the end of June, the cost model shows about six percent savings.', 2);
